INSERT INTO `mkt_term_taxonomy` VALUES('23', '23', 'product_cat', '', '0', '1');
INSERT INTO `mkt_term_taxonomy` VALUES('24', '24', 'product_cat', 'Nesta área a Triónica Moçambique está dotada de Equipamento de gama para laboratórios de Instituições de ensino e outras entidades e é reconhecida pela qualidade e inovações técnicas dos seus produtos.\r\n\r\nHoje somos expressivos no fornecimento de: Equipamentos Didáticos e Científicos, Equipamento de Geofísica, Quadros Interativos, Mobiliário Escolar e de Laboratório, entre outros.\r\n\r\nO nosso trabalho é baseado na parceria, com nossos clientes e colaboradores, que nos permite ser um dos principais fornecedores de produtos para laboratórios, com qualidade, durabilidade e resultados precisos nos equipamentos por nós fornecidos.\r\n', '0', '0');
INSERT INTO `mkt_term_taxonomy` VALUES('25', '25', 'product_cat', '', '0', '0');
INSERT INTO `mkt_term_taxonomy` VALUES('26', '26', 'product_cat', 'Com o objectivo de fornecer materiais e equipamentos para salvar vidas e manter a integridade física das pessoas, a Triónica Moçambique, empresa de prestígio e sucesso, comercializa equipamentos médicos e produtos para a saúde levando a mais alta tecnologia em produtos e serviços hospitalares aos seus clientes, garantindo que os mesmos fiquem satisfeitos com a qualidade dos nossos serviços e atendimento.\r\n\r\nNesta área dispomos de uma vasta gama de equipamentos tais como: Equipamentos Laboratoriais, Equipamentos Hospitalares, Mobiliário Hospitalar e de Laboratório.\r\n', '0', '1');
INSERT INTO `mkt_term_taxonomy` VALUES('27', '27', 'product_cat', '', '26', '3');
INSERT INTO `mkt_term_taxonomy` VALUES('28', '28', 'product_cat', '', '24', '4');
INSERT INTO `mkt_term_taxonomy` VALUES('30', '30', 'product_cat', '', '0', '0');
INSERT INTO `mkt_term_taxonomy` VALUES('31', '31', 'product_cat', '', '0', '0');
INSERT INTO `mkt_term_taxonomy` VALUES('32', '32', 'product_cat', 'O nosso diferencial nesta área destaca-se na disponibilização de uma vasta gama de equipamentos para Análise e Tratamento de Águas, Monitorização Costeira e de barragens, irrigação, equipamentos de medicação, produtos químicos, entre outros.\r\n\r\nO nosso foco é proporcionar aos nossos clientes facilidade na aquisição de equipamentos para melhoramento da qualidade de água,  e para tal apresentamos soluções tecnológicas inovadoras com vista a obtenção de patamares elevados de competitividade e lucratividade.\r\n', '0', '4');
INSERT INTO `mkt_term_taxonomy` VALUES('33', '33', 'product_cat', '', '32', '3');
INSERT INTO `mkt_term_taxonomy` VALUES('34', '34', 'product_cat', '', '32', '3');
INSERT INTO `mkt_term_taxonomy` VALUES('35', '35', 'product_cat', '', '32', '3');
INSERT INTO `mkt_term_taxonomy` VALUES('36', '36', 'product_cat', 'A Triónica Moçambique oferece nesta área diversos equipamentos laboratoriais e de campo para Análise de Solo, Análise de Águas, Análise da Qualidade do Ar, Clima e Oceanografia. Neste âmbito, fornecemos equipamentos de gama à diversas Universidades, Instituições de ensino e outras entidades ligadas a agricultura e meio ambiente.\r\n\r\nNosso grande propósito é oferecer soluções sustentáveis para a agricultura e ambiente, contribuindo para que as instituições ligadas a esta área encontrem meios práticos e seguros para produzir em sistemas diferenciados, atendendo os requisitos de normas de produção orgânica nacional.\r\n', '0', '5');
INSERT INTO `mkt_term_taxonomy` VALUES('37', '37', 'product_cat', '', '36', '0');
INSERT INTO `mkt_term_taxonomy` VALUES('38', '38', 'product_cat', '', '36', '0');
INSERT INTO `mkt_term_taxonomy` VALUES('39', '39', 'product_cat', 'Nesta área de actuação somos pioneiros em fornecimento de diversos equipamentos tais como: Equipamento de Diagrafia para águas subterrâneas, Kits de análise de metais pesados nas águas, Equipamentos Sísmicos, Equipamentos para Resistividade, entre outros…\r\n\r\nOs desafios do sector mineiro qualificam a Triónica Moçambique a atender outras necessidades emergentes, e para o efeito dispomos de Engenheiros, Projetistas e Técnicos especializados, prontos para desenvolver projectos de complexidade variada e com preocupação constante com a sociedade e o meio ambiente. Contamos ainda com profissionalismo e comprometimento não só da nossa equipe como de nossos fabricantes.\r\n', '0', '2');
